fn tree(ext: bool, h: &str) -> kobo_web_document::style_tree::StyleTree {
    if ext {
        parse_style_tree_with_inline_sheets_and_selectors(h.as_bytes(), &[], &Limits::DEFAULT, None, SupplyBudget::CANONICAL)
    } else {
        parse_style_tree(h.as_bytes(), &[], &Limits::DEFAULT)
    }
}
fn fmt(n: u32) -> String {
    let s = format!("{:.5}", f64::from(n) / 100_000.0);
    s.trim_end_matches('0').to_string()
}
fn used(ext: bool, n: &str, s: u32) -> Option<Option<u32>> {
    let t = tree(ext, &format!("<!doctype html><p style='font-size:{s}px;line-height:{n}'>x</p>"));
    if t.unsupported { return None; }
    let node = t.nodes.iter().find(|n| n.tag == "p")?;
    Some(node.style.used_line_height(7))
}
fn decimals(n: u32) -> usize { fmt(n).split('.').nth(1).map_or(0, str::len) }
#[test]
fn whole_pixel_results_match_chrome_and_everything_else_refuses() {
    let (mut admitted, mut refused) = (0, 0);
    for &(n, s, h) in CHROME {
        if decimals(n) < 3 { continue; }
        let got = used(true, &fmt(n), s);
        let exact64 = u64::from(s) * u64::from(n) * 64 / 100_000;
        let engine_whole = exact64 % 64 == 0;
        if h.fract() == 0.0 && engine_whole {
            assert_eq!(got, Some(Some(h as u32)), "{} @ {s}px Chrome {h}", fmt(n));
            admitted += 1;
        } else {
            // Chrome fractional, or Chrome whole only through float rounding the exact math does not share: refuse.
            assert!(matches!(got, None | Some(None)), "{} @ {s}px Chrome {h} must refuse, got {got:?}", fmt(n));
            refused += 1;
        }
    }
    assert!(admitted > 50 && refused > 100, "sample sanity: admitted {admitted} refused {refused}");
}
#[test]
fn chrome_discriminating_pairs_refuse_not_admit() {
    // plain double floor says whole pixel, Chrome's float-percent path says +1/64: must refuse.
    for (n, s) in [("2.90282", 41), ("1.12678", 79), ("1.35123", 94), ("2.63199", 38)] {
        assert!(matches!(used(true, n, s), None | Some(None)), "{n} @ {s}");
    }
}
#[test]
fn default_entry_still_refuses_three_to_five_decimals() {
    for &(n, s, _) in CHROME {
        if decimals(n) < 3 { continue; }
        let got = used(false, &fmt(n), s);
        assert!(matches!(got, None | Some(None)), "default {} @ {s}px must refuse, got {got:?}", fmt(n));
    }
}
#[test]
fn one_and_two_decimals_are_unchanged() {
    for ext in [false, true] {
        assert_eq!(used(ext, "1.15", 20), Some(Some(23)));
        assert_eq!(used(ext, "1.25", 16), Some(Some(20)));
        assert!(matches!(used(ext, "1.15", 16), None | Some(None)));
    }
}
#[test]
fn six_decimals_refuse_even_ext() {
    for n in ["1.123456", "1.0000001"] {
        assert!(matches!(used(true, n, 16), None | Some(None)), "{n}");
    }
}
#[test]
fn old_public_hundredths_domain_is_not_reinterpreted() {
    // Previous LH1 used the u32 high bit inside LineHeightNumber, which aliased old large values:
    // 21475836.48 -> 2147583648 == 0x8000_0000 | 100_000 would have meant multiplier 1.0. Old behaviour: overflow refusal.
    for big in [2_147_583_648u32, 2_147_483_648, 4_294_967_295] {
        let rules = [Declaration {
            property: Property::LineHeight,
            value: Value::LineHeightNumber(big),
            origin: Origin::Author,
            important: false,
            specificity: (0, 1, 0),
            source_order: 0,
        }];
        let mut c = Computed::cascade(None, &rules);
        c.font_size = 16;
        assert_eq!(c.line_height_precise, None);
        assert_eq!(c.line_height_number, Some(big));
        assert_eq!(c.used_line_height(7), None, "{big}");
    }
    for ext in [false, true] {
        assert!(matches!(used(ext, "21475836.48", 16), None | Some(None)));
    }
    // Normal old values still work through the public type.
    let rules = [Declaration {
        property: Property::LineHeight,
        value: Value::LineHeightNumber(125),
        origin: Origin::Author,
        important: false,
        specificity: (0, 1, 0),
        source_order: 0,
    }];
    let mut c = Computed::cascade(None, &rules);
    c.font_size = 16;
    assert_eq!(c.used_line_height(7), Some(20));
}
#[test]
fn precise_value_inherits_as_number_and_recomputes_at_child_font_size() {
    // Chrome 156 inner heights: (1.31579, parent 19px, child 38px) = 50; (1.04167, 24px, 48px) = 50;
    // (1.31579, 19, 16) = 21.046875 and (2.63199, 38, 38) = 100.015625 refuse.
    let cases: [(&str, u32, u32, Option<u32>); 4] =
        [("1.31579", 19, 38, Some(50)), ("1.04167", 24, 48, Some(50)), ("1.31579", 19, 16, None), ("2.63199", 38, 38, None)];
    for (n, ps, cs, want) in cases {
        let t = tree(true, &format!(
            "<!doctype html><div style='font-size:{ps}px;line-height:{n}'><div style='font-size:{cs}px'>x</div></div>"));
        let inner = t.nodes.iter().filter(|x| x.tag == "div").nth(1).expect("inner div");
        assert_eq!(inner.style.font_size, cs);
        assert_eq!(inner.style.used_line_height(7), want, "{n} {ps}->{cs}");
    }
}
#[test]
fn later_old_domain_declaration_replaces_precise_and_child_inherits_precise_field() {
    let d = |value, order| Declaration {
        property: Property::LineHeight,
        value,
        origin: Origin::Author,
        important: false,
        specificity: (0, 1, 0),
        source_order: order,
    };
    let rules = [d(Value::LineHeightPrecise(131_579), 0), d(Value::LineHeightNumber(125), 1)];
    let c = Computed::cascade(None, &rules);
    assert_eq!((c.line_height_precise, c.line_height_number), (None, Some(125)));
    let parent = Computed::cascade(None, &[d(Value::LineHeightPrecise(131_579), 0)]);
    assert_eq!(parent.line_height_precise, Some(131_579));
    let child = Computed::cascade(Some(parent), &[]);
    assert_eq!(child.line_height_precise, Some(131_579));
    let overridden = Computed::cascade(Some(parent), &[d(Value::LineHeightNumber(125), 0)]);
    assert_eq!((overridden.line_height_precise, overridden.line_height_number), (None, Some(125)));
}

